class MidiNoteSpecification(MockObject):
    """An object specifying the data for creating a MIDI note. To be used with the
    add_new_notes function.
    """
    def __init__(self, pitch: int, start_time: float, duration: float, velocity: float=100.0, mute: bool=False, probability: float=1.0, velocity_deviation: float=0.0, release_velocity: float=64.0) -> None:
        super().__init__(pitch=pitch, start_time=start_time, duration=duration, velocity=velocity, mute=mute, probability=probability, velocity_deviation=velocity_deviation, release_velocity=release_velocity)


class MidiNoteVector(Vector):
    """A container for holding MIDI notes from Live."""
    def append(self, value) -> None:
        self._append(value)
    def extend(self, value) -> None:
        self._extend(value)


class WarpMarker(MockObject):
    """This class represents a WarpMarker type."""
    def __init__(self, sample_time: float, beat_time: float) -> None:
        super().__init__(sample_time=sample_time, beat_time=beat_time)

    @property
    def beat_time(self) -> float:
        """A WarpMarker's beat time."""
        return self._get('beat_time', 0.0)

    @property
    def sample_time(self) -> float:
        """A WarpMarker's sample time."""
        return self._get('sample_time', 0.0)


class WarpMarkerVector(Vector):
    """A container for returning warp markers from Live."""
    def append(self, value) -> None:
        self._append(value)
    def extend(self, value) -> None:
        self._extend(value)


